def predict(history, action):
    kind = int(action.kind)
    frame = history.frames[-1]
    grid = np.array(frame, dtype=np.int8)

    if kind == 6:
        row = int(action.row)
        col = int(action.col)
        if 0 <= row < 64 and 0 <= col < 64:
            current_val = grid[row, col]
            if current_val == 14:
                grid[row, col] = 11
            elif current_val == 11:
                grid[row, col] = 14
    elif kind == 4:
        # ACTION4: Move/Shift (arrow-like behavior inferred from history patterns)
        # Shift the large blue component (value 10) up by one row if possible
        blue_mask = (grid == 10)
        if np.any(blue_mask):
            new_grid = grid.copy()
            rows = np.where(blue_mask)[0]
            cols = np.where(blue_mask)[1]
            if len(rows) > 0 and rows[-1] > 0:
                new_grid[rows[0], cols] = grid[rows[0]+1, cols]
                new_grid[rows[-1]+1, cols] = 0
                new_grid[rows[-1], cols] = 10
                grid = new_grid

    return {"next_grid": grid, "game_state": "NOT_FINISHED", "level_delta": 0, "memory": {}}

