    frame = history.frames[-1]
    grid = np.array(frame, dtype=np.int8)

    # Identify the main blue component (value 10)
    blue_mask = (grid == 10)
    if not np.any(blue_mask):
        return 0.0

    blue_count = np.count_nonzero(blue_mask)
    if blue_count == 0:
        return 0.0

    # Calculate progress based on how much of the blue component is at the bottom
    # or how close it is to the target area (bottom section)
    blue_rows = np.where(blue_mask)[0]

    if len(blue_rows) > 0:
        bottom_rows = blue_rows[blue_rows >= 32]
        if len(bottom_rows) > 0:
            # Progress increases as more blue cells are in the bottom half
            bottom_ratio = len(bottom_rows) / len(blue_rows)
            return 0.5 + 0.25 * bottom_ratio
        else:
            # All blue is in top half, start from lower value
            return 0.25 + 0.25 * (1 - (blue_rows[0] / 32))
    else:
        return 0.0

