def goal_value(history):
    n_frames = len(history.frames)
    if n_frames == 0:
        return 0.0
    frame = history.frames[-1]
    palette = np.unique(frame)
    if len(palette) == 0:
        return 0.0
    frame = frame.astype(np.float32)
    min_val = np.min(frame)
    max_val = np.max(frame)
    if min_val == max_val:
        return 0.0
    progress = (frame - min_val) / (max_val - min_val)
    mean_progress = np.mean(progress)
    return np.clip(mean_progress, 0.0, 1.0)
